root.css:
/* The page is a full-width form (width 100%); the content column is 1200 px and centred with calc(). */
min-width: 1200px;
/* Design tokens: usable everywhere on the page, also in the "CSS style" rows of single controls */
--navy: #0f2a43;
--amber: #ffb400;
--muted: #5b6f82;
font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
color: var(--navy);
scroll-margin-top: 0;

/* buttons: put the class name in the HTML attribute "class" of a button */
.btn-primary {
  border: 0; border-radius: 999px; cursor: pointer;
  background: var(--amber); color: var(--navy); font-weight: 700;
  transition: transform .15s, filter .15s;
}
.btn-primary:hover { transform: translateY(-2px); filter: brightness(1.08); }
.btn-ghost {
  border: 2px solid rgba(255,255,255,.55); border-radius: 999px; cursor: pointer;
  background: transparent; color: #fff; font-weight: 700;
}
.btn-ghost:hover { background: rgba(255,255,255,.12); }
.btn-round {
  border: 0; border-radius: 50%; cursor: pointer; font-size: 22px; line-height: 1;
  background: rgba(255,255,255,.14); color: #fff;
}
.btn-round:hover { background: var(--amber); color: var(--navy); }

/* surfaces */
.card {
  border-radius: 18px; background: #fff;
  box-shadow: 0 6px 24px rgba(15,42,67,.10);
  transition: transform .2s, box-shadow .2s;
}
.card:hover { transform: translateY(-4px); box-shadow: 0 16px 36px rgba(15,42,67,.18); }
.glass {
  border-radius: 22px; box-shadow: none;
  background: rgba(255,255,255,.09); border: 1px solid rgba(255,255,255,.2);
}
.calc { border-radius: 26px; box-shadow: none; background: linear-gradient(120deg, #ffe7a8, #ffd25a); }
.quotes { border-radius: 26px; box-shadow: none; background: linear-gradient(120deg, #0f2a43, #1f5580); }
.results { border-radius: 20px; box-shadow: 0 8px 28px rgba(15,42,67,.16); }
.pic { border-radius: 24px; box-shadow: 0 14px 40px rgba(15,42,67,.2); }

/* inline anchor links inside HTML controls */
.cta:hover { filter: brightness(1.08); }
.ghost:hover { background: rgba(255,255,255,.12); }
a { transition: color .15s; }

/* form fields: one look for every textbox, combobox and textarea on the page, also inside components */
input[type=text], select, textarea {
  border: 1px solid #c9d6e2; border-radius: 10px; background: #fff;
  padding: 0 12px; outline: none;
}
textarea { padding: 10px 12px; }
input[type=text]:focus, select:focus, textarea:focus { border-color: var(--amber); box-shadow: 0 0 0 3px rgba(255,180,0,.3); }
input[type=range], input[type=checkbox] { accent-color: var(--amber); }

.muted { color: var(--muted); }

/* TeamCard */
.avatar { border-radius: 50%; color: #0f2a43; box-shadow: 0 6px 16px rgba(15,42,67,.18); }
.bio { border-radius: 18px; }

/* FaqItem */
.faqq { text-align: left; border: 0; background: transparent; cursor: pointer; }
.faqq:hover { color: #d98f00; }
